import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import { measureSpeechProbe } from "../src/measureSpeechProbe";

/**
 * Decode every original WAV before writing a candidate measurement report.
 * Supply output.json followed by input WAV paths. Reads are sequential and
 * file handles close through readFile/writeFile. No audio is trimmed, accepted
 * by listening, wired into playback or generated by this measurement command.
 */
async function main(args: string[]): Promise<void> {
  const output: string | undefined = args[0];
  const inputs: string[] = args.slice(1);
  if (output === undefined || inputs.length === 0)
    throw new Error("Supply output.json and at least one original WAV");

  const measurements: (ReturnType<typeof measureSpeechProbe> & {
    path: string;
  })[] = [];
  for (const input of inputs) {
    const absolute: string = path.resolve(input);
    const bytes: Buffer = await readFile(absolute);
    measurements.push({
      path: absolute.replaceAll("\\", "/"),
      ...measureSpeechProbe(bytes, absolute),
    });
  }

  await writeFile(
    path.resolve(output),
    `${JSON.stringify(
      {
        decoder: "@automovie/ingest",
        listening: "unverified; technical measurements do not establish words or suitability",
        measurements,
      },
      null,
      2,
    )}\n`,
  );
}

void main(process.argv.slice(2)).catch((error: unknown): void => {
  console.error(error);
  process.exitCode = 1;
});
